import Login from "./Login";
import Signup from "./Signup";
import { useState } from "react";

function App() {
  const [page, setPage] = useState("login");

  return (
    <div>
      {page === "login" ? (
        <Login goSignup={() => setPage("signup")} />
      ) : (
        <Signup goLogin={() => setPage("login")} />
      )}
    </div>
  );
}

export default App;
